package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OptionBuilder.create(String)
 */
public class OptionBuilder_create_TriageGen0Test {

    @Test
    public void testCreateWithValidString() {
        String opt = "a";
        Option option = OptionBuilder.withDescription("desc")
                .withLongOpt("long")
                .isRequired()
                .hasArg()
                .withArgName("argName")
                .withValueSeparator(':')
                .withType(String.class)
                .create(opt);

        assertNotNull(option);
        assertEquals(opt, option.getOpt());
        assertEquals("long", option.getLongOpt());
        assertEquals("desc", option.getDescription());
        assertTrue(option.isRequired());
        assertTrue(option.hasArg());
        assertEquals("argName", option.getArgName());
        assertEquals(':', option.getValueSeparator());
        assertEquals(String.class, option.getType());
    }

    @Test
    public void testCreateWithLongOptAndArgs() {
        Option option = OptionBuilder.withLongOpt("longopt")
                .hasArgs(2)
                .hasOptionalArg()
                .create("b");

        assertNotNull(option);
        assertEquals("b", option.getOpt());
        assertEquals("longopt", option.getLongOpt());
        assertEquals(2, option.getArgCount());
        assertTrue(option.hasOptionalArg());
    }

    @Test
    public void testCreateResetBehavior() {
        // First creation
        OptionBuilder.withLongOpt("first").create("a");

        // Second creation should be clean due to OptionBuilder.reset() inside create()
        Option option2 = OptionBuilder.create("b");

        assertNotNull(option2);
        assertEquals("b", option2.getOpt());
        assertNull(option2.getLongOpt());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateWithNullString() {
        // Depending on implementation, passing null might throw IllegalArgumentException
        // if the underlying Option constructor validates it.
        OptionBuilder.create(null);
    }

    @Test
    public void testCreateWithVariousArgTypes() {
        // Test hasOptionalArgs(int)
        Option option = OptionBuilder.hasOptionalArgs(3).create("c");
        assertEquals(3, option.getArgCount());
        assertTrue(option.hasOptionalArg());

        // Test hasArg(boolean)
        Option option2 = OptionBuilder.hasArg(false).create("d");
        assertFalse(option2.hasArg());
    }

    @Test
    public void testCreateWithBooleanRequired() {
        Option option = OptionBuilder.isRequired(false).create("e");
        assertFalse(option.isRequired());

        Option option2 = OptionBuilder.isRequired(true).create("f");
        assertTrue(option2.isRequired());
    }

    @Test
    public void testCreateWithValueSeparator() {
        Option option = OptionBuilder.withValueSeparator().create("g");
        // Default separator behavior check if applicable, usually null or default
        assertNotNull(option);

        Option option2 = OptionBuilder.withValueSeparator(',').create("h");
        assertEquals(',', option2.getValueSeparator());
    }
}
